\operatorname{ren}(b_y(E),x,z)=
\begin{cases}
b_y(E)&y=x,\\
b_y(\operatorname{ren}(E,x,z))&y\ne x,\ y\ne z,\\
b_w(\operatorname{ren}(\operatorname{ren}(E,y,w),x,z))&y\ne x,\ y=z,
\end{cases}

b_y(E)[x:=s]=\begin{cases}
b_y(E)&y=x,\\
b_y(E[x:=s])&y\ne x,\ y\notin FV(s),\\
b_z(\operatorname{ren}(E,y,z)[x:=s])&y\ne x,\ y\in FV(s),
\end{cases}
\quad z=\operatorname{fresh}_{\mathsf{Pure}}(FV(E)\cup FV(s)\cup\{x,y\}).
